DROP TRIGGER IF EXISTS t_authhost_set_dirtyauthhost ON authhost CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_authhost_set_dirtyauthhost() RETURNS trigger AS $BODY$
DECLARE

  S_PREFIX CONSTANT varchar(64) := 'auth.t_authhost_set_dirtyauthhost(): ';
BEGIN
  BEGIN

  
  
  IF ((OLD.backupstatus IS NOT NULL) AND (OLD.backupstatus != coalesce(NEW.backupstatus, -1))) THEN
    UPDATE dirtyauthhost
      SET login = 1, token = 1, groups = 1, login2groups = 1, tunnelgroup = 1, login2tunnelgroup = 1
      WHERE authhost_id = NEW.backupauthhost_id;

    IF (FOUND) THEN
      plog.debug(S_PREFIX||'updated dirtyauthhost entry for backup authhost id "'||NEW.backupauthhost_id||'"');
    ELSE
      INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
        VALUES (NEW.backupauthhost_id, 1, 1, 1, 1, 1, 1, 1);

      plog.debug(S_PREFIX||'inserted dirtyauthhost entry for backup authhost id "'||NEW.backupauthhost_id||'"');
    END IF;
  END IF;


  UPDATE dirtyauthhost
    SET login = 1, token = 1, groups = 1, login2groups = 1, tunnelgroup = 1, login2tunnelgroup = 1
    WHERE authhost_id = NEW.id;

  IF (FOUND) THEN
    plog.debug(S_PREFIX||'updated dirtyauthhost entry for master authhost id "'||NEW.id||'"');
  ELSE
    INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
      VALUES (NEW.id, 1, 1, 1, 1, 1, 1, 1);

    plog.debug(S_PREFIX||'inserted dirtyauthhost entry for master authhost id "'||NEW.id||'"');
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    plog.err(S_PREFIX||'caught exception: '||sqlerrm);
    RAISE;

  END;
RETURN NEW;
END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_authhost_set_dirtyauthhost() FROM PUBLIC;

CREATE TRIGGER t_authhost_set_dirtyauthhost
	AFTER INSERT OR UPDATE OF host_id,backupstatus ON authhost FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_authhost_set_dirtyauthhost();

DROP TRIGGER IF EXISTS t_companytype_aserto ON comp_comptype_ref CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_companytype_aserto() RETURNS trigger AS $BODY$
DECLARE
  v_cust_group bigint;
  v_company_group_old bigint;
  v_company_group_new bigint;
BEGIN
  if coalesce(NEW.COMPTYPE_ID, OLD.COMPTYPE_ID) = 1 then

    select CASE WHEN c.SWISS_ONLY_OPS=0 THEN  1 WHEN c.SWISS_ONLY_OPS=1 THEN  3 END  into STRICT v_cust_group
    from stop.company c where c.id = coalesce(NEW.company_id, OLD.company_id);
    v_company_group_old := v_cust_group;
    if OLD.company_id  = 6 then

      v_company_group_old := 2;
    end if;
    v_company_group_new := v_cust_group;
    if NEW.company_id  = 6 then

      v_company_group_new := 2;
    end if;
    aserto.PublishAsertoUpdate(
    'company_group',
    v_company_group_old,
    v_company_group_new,
    'parent_company_group',
    'company',
    OLD.company_id,
    NEW.company_id
    );
  end if;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_companytype_aserto() FROM PUBLIC;

CREATE TRIGGER t_companytype_aserto
	AFTER INSERT OR DELETE ON comp_comptype_ref FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_companytype_aserto();

