DROP TRIGGER IF EXISTS t_company_aserto ON company CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_company_aserto() RETURNS trigger AS $BODY$
DECLARE
  s RECORD;
  v_is_cust bigint;
  v_group_old bigint;
  v_group_new bigint;
  v_cu_old bigint;
  v_cu_new bigint;
BEGIN
  BEGIN

  BEGIN
    v_is_cust := 0;
    select CASE WHEN company_id=6 THEN  0  ELSE 1 END  into STRICT v_is_cust
      from stop.COMP_COMPTYPE_REF
     where company_id = coalesce(NEW.id, OLD.id)
       and COMPTYPE_ID = 1;
  exception
    when no_data_found then
      RETURN NEW;
  end;

  if v_is_cust = 1 then

    select CASE WHEN OLD.swiss_only_ops=0 THEN  1 WHEN OLD.swiss_only_ops=1 THEN  3 END  into STRICT v_group_old;
    select CASE WHEN NEW.swiss_only_ops=0 THEN  1 WHEN NEW.swiss_only_ops=1 THEN  3 END  into STRICT v_group_new;


    aserto.PublishAsertoUpdate(
    'company_group',
    v_group_old,
    v_group_new,
    'parent_company_group',
    'company',
    OLD.id,
    NEW.id
    );
  end if;

  for s in (
    SELECT s.id, s.company_unit_id
    from mss.service s
    where s.COMPANY_ID = coalesce(NEW.id, OLD.id)
    ) loop

      v_cu_old := s.company_unit_id;
      if v_cu_old is null then
        v_cu_old := OLD.DEFAULT_COMPANY_UNIT_ID;
      end if;
      v_cu_new := s.company_unit_id;
      if v_cu_new is null then
        v_cu_new := NEW.DEFAULT_COMPANY_UNIT_ID;
      end if;

      aserto.PublishAsertoUpdate(
      'company_unit',
      v_cu_old,
      v_cu_new,
      'parent_company_unit',
      'service',
      s.id,
      s.id
      );
  end loop;

  END;
RETURN NEW;
END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_company_aserto() FROM PUBLIC;

CREATE TRIGGER t_company_aserto
	AFTER UPDATE OF swiss_only_ops,default_company_unit_id ON company FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_company_aserto();

DROP TRIGGER IF EXISTS t_groups_set_dirtyauthhost ON groups CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_groups_set_dirtyauthhost() RETURNS trigger AS $BODY$
DECLARE

  S_PREFIX CONSTANT varchar(64) := 'auth.t_groups_set_dirtyauthhost(): ';

  c_authhost2authsys CURSOR(p_authsys_id groups.authsys_id%TYPE) FOR
    SELECT authhost_id
      FROM authhost2authsys
      WHERE authsys_id = p_authsys_id;
BEGIN
  BEGIN

  IF (OLD.authsys_id IS NOT NULL) THEN
    FOR r_authhost2authsys IN c_authhost2authsys(OLD.authsys_id) LOOP
      UPDATE dirtyauthhost
	SET groups = 1
	WHERE authhost_id = r_authhost2authsys.authhost_id;

      IF (FOUND) THEN
	plog.debug(S_PREFIX||'updated dirtyauthhost.groups entry for old authhost id "'||r_authhost2authsys.authhost_id||'"');
      ELSE
        INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
          VALUES (r_authhost2authsys.authhost_id, 0, 0, 1, 0, 0, 0, 0);

        plog.debug(S_PREFIX||'inserted dirtyauthhost.groups entry for old authhost id "'||r_authhost2authsys.authhost_id||'"');
      END IF;
    END LOOP;
  END IF;

  IF ((NEW.authsys_id IS NOT NULL) AND (coalesce(OLD.authsys_id, -1) != NEW.authsys_id)) THEN
    FOR r_authhost2authsys IN c_authhost2authsys(NEW.authsys_id) LOOP
      UPDATE dirtyauthhost
	SET groups = 1
	WHERE authhost_id = r_authhost2authsys.authhost_id;

      IF (FOUND) THEN
	plog.debug(S_PREFIX||'updated dirtyauthhost.groups entry for new authhost id "'||r_authhost2authsys.authhost_id||'"');
      ELSE
        INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
          VALUES (r_authhost2authsys.authhost_id, 0, 0, 1, 0, 0, 0, 0);

        plog.debug(S_PREFIX||'inserted dirtyauthho.groups entry for new authhost id "'||r_authhost2authsys.authhost_id||'"');
      END IF;
    END LOOP;
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    plog.err(S_PREFIX||'caught exception: '||sqlerrm);
    RAISE;

  END;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_groups_set_dirtyauthhost() FROM PUBLIC;

CREATE TRIGGER t_groups_set_dirtyauthhost
	AFTER INSERT OR UPDATE OR DELETE OF id,name,authsys_id ON groups FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_groups_set_dirtyauthhost();

DROP TRIGGER IF EXISTS t_hardware_disposal ON hardware CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_hardware_disposal() RETURNS trigger AS $BODY$
DECLARE

  S_PREFIX CONSTANT varchar(64) := 'mss.t_hardware_disposal(): ';
  l_type_name    mss.hardware_type.name%TYPE := NULL;
BEGIN
  BEGIN

  IF (NEW.disposal_date IS NOT NULL ) THEN
    BEGIN
      SELECT name INTO STRICT l_type_name FROM mss.hardware_type
        WHERE id = NEW.hardware_type_id;
    EXCEPTION
      WHEN OTHERS THEN
        l_type_name := NULL;
    END;
    plog.notice('hardware disposal: '
      ||'hardware_id='       ||NEW.id
      ||',hardware_type='    ||coalesce(l_type_name,'NULL')
      ||',barcode='          ||coalesce(NEW.barcode,'NULL')
      ||',serial_number='    ||coalesce(NEW.serial_number,'NULL')
      ||',mac_address='      ||coalesce(NEW.mac_address,'NULL')
      ||',purchase_date='    ||coalesce(TO_CHAR(NEW.purchase_date,'dd.mm.yyyy'),'NULL')
      ||',disposal_date='    ||coalesce(TO_CHAR(NEW.disposal_date,'dd.mm.yyyy'),'NULL')
    );
  END IF;

EXCEPTION

  WHEN OTHERS THEN
    plog.err(S_PREFIX||'caught exception: '||sqlerrm);

  END;
RETURN NEW;
END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
