DROP TRIGGER IF EXISTS t_login_set_company ON login CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_login_set_company() RETURNS trigger AS $BODY$
DECLARE
  r RECORD;
  v_company_id STOP.COMPANY.ID%TYPE := 0;
  v_user_unit_id AUTH.USER_UNIT.ID%TYPE := 0;
BEGIN
  BEGIN

  BEGIN
    SELECT company_id INTO STRICT v_company_id FROM stop.contact c WHERE c.id = NEW.contact_id;

    NEW.company_id := v_company_id;
  EXCEPTION
    WHEN no_data_found THEN
      NEW.company_id := NULL;
    WHEN OTHERS THEN
      plog.err('t_login_set_company: caught exception: '||sqlerrm);
  END;

  IF TG_OP = 'INSERT' THEN
    BEGIN
      IF (NEW.user_unit_id IS NULL) THEN
        SELECT id INTO STRICT v_user_unit_id FROM auth.user_unit u WHERE u.company_id = v_company_id AND u.default_unit = 1;
        NEW.user_unit_id := v_user_unit_id;
      END IF;
    EXCEPTION
      WHEN no_data_found THEN
        NEW.user_unit_id := NULL;
      WHEN OTHERS THEN
        plog.err('t_login_set_company: caught exception: '||sqlerrm);
    END;
  END IF;

  IF (TG_OP = 'INSERT' and NEW.OIDC_ZITADEL_ID is not null) or (TG_OP = 'UPDATE' and NEW.OIDC_ZITADEL_ID is not null and OLD.OIDC_ZITADEL_ID is null) THEN

     
     for r in (SELECT CASE WHEN ur.NAME='mc-osag-monitor' THEN  'mc_engineer_viewer' WHEN ur.NAME='mc-osag-admin' THEN  'mc_engineer_with_users_editor' END  rel1,
                      CASE WHEN ur.NAME='mc-osag-monitor' THEN  'mc_engineer_viewer' WHEN ur.NAME='mc-osag-admin' THEN  'mc_engineer_editor' END  rel2,
                     coalesce(NEW.OIDC_ZITADEL_ID, OLD.OIDC_ZITADEL_ID) user_id
              from auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p
              where ur.NAME in ('mc-osag-monitor', 'mc-osag-admin')
                and l2p.PROFILE_ID = up.PROFILE_ID
                and l2p.LOGIN_ID = coalesce(OLD.id, NEW.id)
                and ur.id = up.USER_ROLE_ID ) loop
       aserto.PublishAsertoAction(
        'create',
        'user',
        r.user_id,
        r.rel1,
        'company_group',
        '1'
       );
       aserto.PublishAsertoAction(
       'create',
       'user',
       r.user_id,
       r.rel2,
       'company_group',
       '2'
       );
     end loop;

     for r in (SELECT CASE WHEN ur.NAME='mc-prx-admin' THEN  'proxy_administrator' WHEN ur.NAME='mc-threat-protection-admin' THEN  'tp_administrator' WHEN ur.NAME='mca-conf-fw-admin' THEN  'firewall_administrator' WHEN ur.NAME='mca-access' THEN  'mca_viewer' WHEN ur.NAME='mca-conf-mgmt' THEN  'mca_editor' WHEN ur.NAME='mca-permission-admin' THEN  'mca_user_editor' WHEN ur.NAME='mca-conf-app-admin' THEN  'app_editor' WHEN ur.NAME='mca-exec' THEN  'ct_editor' WHEN ur.NAME='mca-host-decommission' THEN  'host_deleter' WHEN ur.NAME='mca-hw-admin' THEN  'hw_editor' WHEN ur.NAME='mca-news-publisher' THEN  'news_editor' WHEN ur.NAME='mca-tt-admin' THEN  'tt_editor' WHEN ur.NAME='esp-admin' THEN  'ops_editor'                       END  rel,
                      coalesce(NEW.OIDC_ZITADEL_ID, OLD.OIDC_ZITADEL_ID) user_id
               from auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p
               where ur.NAME in ('mc-prx-admin', 'mc-threat-protection-admin', 'mca-conf-fw-admin',
                                 'mca-access', 'mca-conf-mgmt', 'mca-permission-admin', 'mca-conf-app-admin',
                                 'mca-exec', 'mca-host-decommission', 'mca-hw-admin', 'mca-news-publisher',
                                 'mca-tt-admin', 'esp-admin')
                 and l2p.PROFILE_ID = up.PROFILE_ID
                 and l2p.LOGIN_ID = coalesce(OLD.id, NEW.id)
                 and ur.id = up.USER_ROLE_ID ) loop
         aserto.PublishAsertoAction(
         'create',
         'user',
         r.user_id,
         r.rel,
         'internal_permissions',
         '1'
         );
     end loop;

     for r in (SELECT CASE WHEN ur.NAME='mc-cust-monitor' THEN  'viewer' WHEN ur.NAME='mc-cust-auditor' THEN  'auditor' WHEN ur.NAME='mc-cust-admin' THEN    'editor' WHEN ur.NAME='mc-cust-tp-mgmt' THEN  'tp_self_service_editor' WHEN ur.NAME='mc-cust-prx-config-mgmt' THEN  'proxy_self_service_editor' WHEN ur.NAME='mc-cust-fw-config-mgmt' THEN  'firewall_self_service_editor' WHEN ur.NAME='mc-cust-casb-policy-mgmt' THEN  'casb_self_service_editor' WHEN ur.NAME='mc-cust-mail-config-mgmt' THEN  'mail_self_service_editor' WHEN ur.NAME='mc-cust-api' THEN  'api_access_user' WHEN ur.NAME='mc-cust-api-users-mgmt' THEN  'api_users_self_service_editor' WHEN ur.NAME='mc-cust-incident-resp-mgmt' THEN  'ndr_service_handler' WHEN ur.NAME='mc-cust-sign-off' THEN  'approver' WHEN ur.NAME='mc-cust-users-monitor' THEN  'mep_user_viewer' WHEN ur.NAME='mc-cust-users-auditor' THEN  'mep_user_auditor' WHEN ur.NAME='mc-cust-users-admin' THEN  'mep_user_editor' WHEN ur.NAME='mc-cust-open-systems-identity-users-admin' THEN  'open_systems_identity_user_editor' WHEN ur.NAME='mc-cust-open-systems-identity-users-auditor' THEN  'open_systems_identity_user_auditor' WHEN ur.NAME='mc-cust-open-systems-identity-users-monitor' THEN  'open_systems_identity_user_viewer'                       END  rel,
                      coalesce(NEW.OIDC_ZITADEL_ID, OLD.OIDC_ZITADEL_ID) user_id,
                      ucs.company_id
               from auth.USER_COMPANY_SCOPE ucs, auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p
               where up.USER_ROLE_ID = ur.id
                 and ur.NAME in ('mc-cust-monitor', 'mc-cust-auditor', 'mc-cust-admin',
                                 'mc-cust-tp-mgmt', 'mc-cust-prx-config-mgmt', 'mc-cust-fw-config-mgmt',
                                 'mc-cust-casb-policy-mgmt', 'mc-cust-mail-config-mgmt', 'mc-cust-api',
                                 'mc-cust-api-users-mgmt', 'mc-cust-incident-resp-mgmt', 'mc-cust-sign-off',
                                 'mc-cust-users-monitor', 'mc-cust-users-auditor', 'mc-cust-users-admin',
                                 'mc-cust-open-systems-identity-users-admin', 'mc-cust-open-systems-identity-users-auditor', 'mc-cust-open-systems-identity-users-monitor')
                 and l2p.PROFILE_ID = up.PROFILE_ID
                 and l2p.LOGIN_ID = coalesce(NEW.id, OLD.id)
                 and up.id = ucs.PERMISSION_ID ) loop
       aserto.PublishAsertoAction(
         'create',
         'user',
         r.user_id,
         r.rel,
         'company',
         r.company_id
       );
     end loop;


     for r in (SELECT CASE WHEN ur.NAME='mc-cust-monitor' THEN  'viewer' WHEN ur.NAME='mc-cust-auditor' THEN  'auditor' WHEN ur.NAME='mc-cust-admin' THEN    'editor' WHEN ur.NAME='mc-cust-incident-resp-mgmt' THEN  'ndr_service_handler' WHEN ur.NAME='mc-cust-sign-off' THEN  'approver' WHEN ur.NAME='mc-cust-users-monitor' THEN  'mep_user_view' WHEN ur.NAME='mc-cust-users-auditor' THEN  'mep_user_audit' WHEN ur.NAME='mc-cust-users-admin' THEN  'mep_user_edit'                       END  rel,
                      coalesce(NEW.OIDC_ZITADEL_ID, OLD.OIDC_ZITADEL_ID) user_id,
                      uus.company_unit_id
               from auth.USER_COMPANY_UNIT_SCOPE uus, auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p
               where up.USER_ROLE_ID = ur.id
                 and ur.NAME in ('mc-cust-monitor', 'mc-cust-auditor', 'mc-cust-admin',
                                 'mc-cust-incident-resp-mgmt', 'mc-cust-sign-off',
                                 'mc-cust-users-monitor', 'mc-cust-users-auditor', 'mc-cust-users-admin')
                 and l2p.PROFILE_ID = up.PROFILE_ID
                 and l2p.LOGIN_ID = coalesce(NEW.id, OLD.id)
                 and up.id = uus.PERMISSION_ID ) loop
       aserto.PublishAsertoAction(
         'create',
         'user',
         r.user_id,
         r.rel,
         'company_unit',
         r.company_unit_id
       );
     end loop;


     for r in (SELECT CASE WHEN ur.NAME='mc-cust-monitor' THEN  'viewer' WHEN ur.NAME='mc-cust-auditor' THEN  'auditor' WHEN ur.NAME='mc-cust-admin' THEN    'editor' WHEN ur.NAME='mc-cust-incident-resp-mgmt' THEN  'ndr_service_handler'                       END  rel,
                      coalesce(NEW.OIDC_ZITADEL_ID, OLD.OIDC_ZITADEL_ID) user_id,
                      uss.service_id
               from auth.USER_SERVICE_SCOPE uss, auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p
               where up.USER_ROLE_ID = ur.id
                 and ur.NAME in ('mc-cust-monitor', 'mc-cust-auditor', 'mc-cust-admin',
                                 'mc-cust-incident-resp-mgmt')
                 and l2p.PROFILE_ID = up.PROFILE_ID
                 and l2p.LOGIN_ID = coalesce(NEW.id, OLD.id)
                 and up.id = uss.PERMISSION_ID ) loop
       aserto.PublishAsertoAction(
         'create',
         'user',
         r.user_id,
         r.rel,
         'service',
         r.service_id
       );
     end loop;
  END IF;

  END;
RETURN NEW;
END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_login_set_company() FROM PUBLIC;

CREATE TRIGGER t_login_set_company
	BEFORE INSERT OR UPDATE ON login FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_login_set_company();

DROP TRIGGER IF EXISTS t_passport_alias_set_dirtyauthhost ON passport_alias CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_passport_alias_set_dirtyauthhost() RETURNS trigger AS $BODY$
DECLARE

    S_PREFIX CONSTANT varchar(64) := 'auth.t_passport_alias_set_dirtyauthhost(): ';

    v_authhost_id login.homeauthhost_id%TYPE := NULL;
BEGIN
  BEGIN

    IF (OLD.login_id IS NOT NULL) THEN
        SELECT homeauthhost_id INTO STRICT v_authhost_id
        FROM passport_login WHERE id = OLD.login_id;

        IF v_authhost_id IS NOT NULL THEN
            UPDATE dirtyauthhost
            SET alias = 1
            WHERE authhost_id = v_authhost_id;

            IF (FOUND) THEN
                plog.debug(S_PREFIX || 'updated dirtyauthhost.alias entry for old authhost "' || v_authhost_id || '"');
            ELSE
                INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                VALUES (v_authhost_id, 0, 0, 0, 0, 0, 0, 1);

                plog.debug(S_PREFIX || 'inserted dirtyauthhost.alias entry for old authhost id "' || v_authhost_id || '"');
            END IF;
        END IF;
    END IF;

    IF ((NEW.login_id IS NOT NULL) AND (coalesce(OLD.login_id, -1) != NEW.login_id)) THEN
        SELECT homeauthhost_id INTO STRICT v_authhost_id
        FROM passport_login WHERE id = NEW.login_id;

        IF v_authhost_id IS NOT NULL THEN
            UPDATE dirtyauthhost
            SET alias = 1
            WHERE authhost_id = v_authhost_id;

            IF (FOUND) THEN
                plog.debug(S_PREFIX || 'updated dirtyauthhost.alias entry for new authhost id "' || v_authhost_id || '"');
            ELSE
                INSERT INTO dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                VALUES (v_authhost_id, 0, 0, 0, 0, 0, 0, 1);

                plog.debug(S_PREFIX || 'inserted dirtyauthhost.alias entry for new authhost id "' || v_authhost_id || '"');
            END IF;
        END IF;
    END IF;


EXCEPTION
    WHEN OTHERS THEN
        plog.err(S_PREFIX||'caught exception: '||sqlerrm);
        RAISE;

  END;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_passport_alias_set_dirtyauthhost() FROM PUBLIC;

CREATE TRIGGER t_passport_alias_set_dirtyauthhost
	AFTER INSERT OR UPDATE OR DELETE OF login_id,"alias or delete" ON passport_alias FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_passport_alias_set_dirtyauthhost();

DROP TRIGGER IF EXISTS t_passport_contact_dn_set_dirtyauthhost ON passport_contact_sync CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_passport_contact_dn_set_dirtyauthhost() RETURNS trigger AS $BODY$
DECLARE

    S_PREFIX CONSTANT varchar(64) := 'stop.t_passport_contact_dn_set_dirtyauthhost(): ';

    c_contact_sync_ids2authhost CURSOR(p_old_contact_sync stop.PASSPORT_CONTACT_SYNC.contact_id%TYPE, p_new_contact_sync stop.PASSPORT_CONTACT_SYNC.contact_id%TYPE) FOR
        SELECT homeauthhost_id
        FROM auth.passport_login
        WHERE auth.passport_login.contact_id IN (p_old_contact_sync, p_new_contact_sync);

BEGIN
    FOR res IN c_contact_sync_ids2authhost(OLD.contact_id, NEW.contact_id) LOOP
            IF (res.homeauthhost_id IS NOT NULL) THEN
                UPDATE auth.dirtyauthhost
                SET login = 1
                WHERE authhost_id = res.homeauthhost_id;

                IF (FOUND) THEN
                    plog.debug(S_PREFIX||'updated dirtyauthhost.login entry for old authhost id "'||res.homeauthhost_id||'"');
                ELSE
                    INSERT INTO auth.dirtyauthhost(authhost_id, login, token, groups, login2groups, tunnelgroup, login2tunnelgroup, alias)
                    VALUES (res.homeauthhost_id, 1, 0, 0, 0, 0, 0, 0);
                    plog.debug(S_PREFIX||'inserted dirtyauthhost.login entry for old authhost id "'||res.homeauthhost_id||'"');
                END IF;
            END IF;
        END LOOP;

IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_passport_contact_dn_set_dirtyauthhost() FROM PUBLIC;

CREATE TRIGGER t_passport_contact_dn_set_dirtyauthhost
