DECLARE

    S_PREFIX CONSTANT varchar(64) := 'auth.t_passport_login_set_authtype(): ';
BEGIN
  BEGIN

    IF (NEW.twofactorenabled = 0 AND NEW.authtype_id IS NULL) THEN
        
        NEW.authtype_id := 0;
    ELSIF (NEW.twofactorenabled = 1 AND NEW.authtype_id IS NULL) THEN

        NEW.authtype_id := 1;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        plog.err(S_PREFIX||'caught exception: '||sqlerrm);
        RAISE;

  END;
RETURN NEW;
END
