DECLARE
    v_company_id STOP.COMPANY.ID%TYPE := 0;
    v_user_unit_id AUTH.USER_UNIT.ID%TYPE := 0;
BEGIN
  BEGIN

    BEGIN

        IF (NEW.user_unit_id IS NULL) THEN
