DROP TRIGGER IF EXISTS t_service_aserto ON service CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_service_aserto() RETURNS trigger AS $BODY$
DECLARE
  v_cu_old bigint;
  v_cu_new bigint;
BEGIN
  BEGIN
  aserto.PublishAsertoUpdate(
  'company',
  OLD.company_id,
  NEW.company_id,
  'parent_company',
  'service',
  OLD.id,
  NEW.id
  );

  v_cu_old := OLD.company_unit_id;
  if v_cu_old is null then
    BEGIN
      select c.DEFAULT_COMPANY_UNIT_ID into STRICT v_cu_old
      from stop.COMPANY c
      where c.id = OLD.company_id;
    exception
      when no_data_found then
        v_cu_old := null;
    end;
  end if;
  v_cu_new := NEW.company_unit_id;
  if v_cu_new is null then
    BEGIN
      select c.DEFAULT_COMPANY_UNIT_ID into STRICT v_cu_new
      from stop.COMPANY c
      where c.id = NEW.company_id;
    exception
      when no_data_found then
        v_cu_new := null;
    end;
  end if;

  aserto.PublishAsertoUpdate(
  'company_unit',
  v_cu_old,
  v_cu_new,
  'parent_company_unit',
  'service',
  OLD.id,
  NEW.id
  );
  END;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
