DROP TRIGGER IF EXISTS t_usrcompsc_aserto ON user_company_scope CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_usrcompsc_aserto() RETURNS trigger AS $BODY$
DECLARE
  r RECORD;
  v_perm_id integer;
  v_company_id integer;
  v_action varchar(16);
BEGIN
  if TG_OP = 'INSERT' then
    v_action := 'create';
    v_perm_id := NEW.permission_id;
    v_company_id := NEW.company_id;
  elsif TG_OP = 'DELETE' then
    v_action := 'delete';
    v_perm_id := OLD.permission_id;
    v_company_id := OLD.company_id;
  end if;

  for r in (SELECT CASE WHEN ur.NAME='mc-cust-monitor' THEN  'viewer' WHEN ur.NAME='mc-cust-auditor' THEN  'auditor' WHEN ur.NAME='mc-cust-admin' THEN    'editor' WHEN ur.NAME='mc-cust-tp-mgmt' THEN  'tp_self_service_editor' WHEN ur.NAME='mc-cust-prx-config-mgmt' THEN  'proxy_self_service_editor' WHEN ur.NAME='mc-cust-fw-config-mgmt' THEN  'firewall_self_service_editor' WHEN ur.NAME='mc-cust-casb-policy-mgmt' THEN  'casb_self_service_editor' WHEN ur.NAME='mc-cust-mail-config-mgmt' THEN  'mail_self_service_editor' WHEN ur.NAME='mc-cust-api' THEN  'api_access_user' WHEN ur.NAME='mc-cust-api-users-mgmt' THEN  'api_users_self_service_editor' WHEN ur.NAME='mc-cust-sign-off' THEN  'approver' WHEN ur.NAME='mc-cust-users-monitor' THEN  'mep_user_viewer' WHEN ur.NAME='mc-cust-users-auditor' THEN  'mep_user_auditor' WHEN ur.NAME='mc-cust-users-admin' THEN  'mep_user_editor' WHEN ur.NAME='mc-cust-open-systems-identity-users-admin' THEN  'open_systems_identity_user_editor' WHEN ur.NAME='mc-cust-open-systems-identity-users-auditor' THEN  'open_systems_identity_user_auditor' WHEN ur.NAME='mc-cust-open-systems-identity-users-monitor' THEN  'open_systems_identity_user_viewer'                    END  rel,
                   l.OIDC_ZITADEL_ID user_id
            from auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p, auth.LOGIN l
            where up.USER_ROLE_ID = ur.id
              and ur.NAME in ('mc-cust-monitor', 'mc-cust-auditor', 'mc-cust-admin',
                             'mc-cust-tp-mgmt', 'mc-cust-prx-config-mgmt', 'mc-cust-fw-config-mgmt',
                             'mc-cust-casb-policy-mgmt', 'mc-cust-mail-config-mgmt', 'mc-cust-api',
                             'mc-cust-api-users-mgmt', 'mc-cust-sign-off',
                             'mc-cust-users-monitor', 'mc-cust-users-auditor', 'mc-cust-users-admin',
                              'mc-cust-open-systems-identity-users-admin', 'mc-cust-open-systems-identity-users-auditor', 'mc-cust-open-systems-identity-users-monitor')
              and l2p.PROFILE_ID = up.PROFILE_ID
              and l2p.LOGIN_ID = l.id
              and l.OIDC_ZITADEL_ID is not null
              and up.id = v_perm_id ) loop
      aserto.PublishAsertoAction(
      v_action,
      'user',
      r.user_id,
      r.rel,
      'company',
      v_company_id
      );
    end loop;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
