DROP TRIGGER IF EXISTS t_usrperm_aserto ON user_permission CASCADE;
CREATE OR REPLACE FUNCTION trigger_fct_t_usrperm_aserto() RETURNS trigger AS $BODY$
DECLARE
  r RECORD;
  v_urole_id integer;
  v_profile_id integer;
  v_action varchar(16);
BEGIN
  if TG_OP = 'INSERT' then
    v_action := 'create';
    v_urole_id := NEW.user_role_id;
    v_profile_id := NEW.profile_id;
  elsif TG_OP = 'DELETE' then
    v_action := 'delete';
    v_urole_id := OLD.user_role_id;
    v_profile_id := OLD.profile_id;
  end if;

  for r in (SELECT CASE WHEN ur.NAME='mc-osag-monitor' THEN  'mc_engineer_viewer' WHEN ur.NAME='mc-osag-admin' THEN  'mc_engineer_with_users_editor' END  rel1,
                   CASE WHEN ur.NAME='mc-osag-monitor' THEN  'mc_engineer_viewer' WHEN ur.NAME='mc-osag-admin' THEN  'mc_engineer_editor' END  rel2,
                   l.OIDC_ZITADEL_ID user_id
            from auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p, auth.LOGIN l
            where ur.NAME in ('mc-osag-monitor', 'mc-osag-admin')
              and l2p.PROFILE_ID = v_profile_id
              and l2p.LOGIN_ID = l.id
              and l.OIDC_ZITADEL_ID is not null
              and ur.id = v_urole_id ) loop
      aserto.PublishAsertoAction(
      v_action,
      'user',
      r.user_id,
      r.rel1,
      'company_group',
      '1'
      );

      aserto.PublishAsertoAction(
      v_action,
      'user',
      r.user_id,
      r.rel2,
      'company_group',
      '2'
      );
    end loop;

    for r in (SELECT CASE WHEN ur.NAME='mc-prx-admin' THEN  'proxy_administrator' WHEN ur.NAME='mc-threat-protection-admin' THEN  'tp_administrator' WHEN ur.NAME='mca-conf-fw-admin' THEN  'firewall_administrator' WHEN ur.NAME='mca-access' THEN  'mca_viewer' WHEN ur.NAME='mca-conf-mgmt' THEN  'mca_editor' WHEN ur.NAME='mca-permission-admin' THEN  'mca_user_editor' WHEN ur.NAME='mca-conf-app-admin' THEN  'app_editor' WHEN ur.NAME='mca-exec' THEN  'ct_editor' WHEN ur.NAME='mca-host-decommission' THEN  'host_deleter' WHEN ur.NAME='mca-hw-admin' THEN  'hw_editor' WHEN ur.NAME='mca-news-publisher' THEN  'news_editor' WHEN ur.NAME='mca-tt-admin' THEN  'tt_editor' WHEN ur.NAME='esp-admin' THEN  'ops_editor'                    END  rel,
                   l.OIDC_ZITADEL_ID user_id
            from auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p, auth.LOGIN l
            where ur.NAME in ('mc-prx-admin', 'mc-threat-protection-admin', 'mca-conf-fw-admin',
                              'mca-access', 'mca-conf-mgmt', 'mca-permission-admin', 'mca-conf-app-admin',
                              'mca-exec', 'mca-host-decommission', 'mca-hw-admin', 'mca-news-publisher',
                              'mca-tt-admin', 'esp-admin')
              and l2p.PROFILE_ID = v_profile_id
              and l2p.LOGIN_ID = l.id
              and l.OIDC_ZITADEL_ID is not null
              and ur.id = v_urole_id ) loop
      aserto.PublishAsertoAction(
      'create',
      'user',
      r.user_id,
      r.rel,
      'internal_permissions',
      '1'
      );
    end loop;

IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
