  end if;

  for r in (SELECT CASE WHEN ur.NAME='mc-cust-monitor' THEN  'viewer' WHEN ur.NAME='mc-cust-auditor' THEN  'auditor' WHEN ur.NAME='mc-cust-admin' THEN    'editor' WHEN ur.NAME='mc-cust-incident-resp-mgmt' THEN  'ndr_service_handler' END  rel,
                   l.OIDC_ZITADEL_ID user_id
            from auth.USER_PERMISSION up, auth.USER_ROLE ur, auth.LOGIN2PROFILE l2p, auth.LOGIN l
            where up.USER_ROLE_ID = ur.id
              and ur.NAME in ('mc-cust-monitor', 'mc-cust-auditor', 'mc-cust-admin',
                              'mc-cust-incident-resp-mgmt')
              and l2p.PROFILE_ID = up.PROFILE_ID
              and l2p.LOGIN_ID = l.id
              and l.OIDC_ZITADEL_ID is not null
              and up.id = v_perm_id ) loop
      aserto.PublishAsertoAction(
      v_action,
      'user',
      r.user_id,
      r.rel,
      'service',
      v_service_id
      );
    end loop;
IF TG_OP = 'DELETE' THEN
	RETURN OLD;
ELSE
	RETURN NEW;
END IF;

END
$BODY$
 LANGUAGE 'plpgsql' SECURITY DEFINER;
-- REVOKE ALL ON FUNCTION trigger_fct_t_usrsvcsc_aserto() FROM PUBLIC;

CREATE TRIGGER t_usrsvcsc_aserto
	BEFORE INSERT OR DELETE ON user_service_scope FOR EACH ROW
	EXECUTE PROCEDURE trigger_fct_t_usrsvcsc_aserto();

